function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is an integer from 1 to 100.';
  return null;
}

reference:
function findGameWinner(n) {
  const grundy = new Array(n + 1).fill(0);
  grundy[1] = 0;
  if (n >= 2) {
    grundy[2] = 1;
  }
  for (let k = 3; k <= n; k++) {
    const left = grundy[k - 2] + 1;
    const right = grundy[k - 1] + 1;
    grundy[k] = left ^ right;
  }
  return grundy[n] !== 0;
}

