function findGameWinner(n) {
  // Every distinct tree shape gets an id; a shape is the sorted list of its children's ids.
  const ids = new Map();
  const kidsOf = [];
  const shape = kids => {
    const sorted = [...kids].sort((x, y) => x - y);
    const key = sorted.join(',');
    if (!ids.has(key)) { ids.set(key, kidsOf.length); kidsOf.push(sorted); }
    return ids.get(key);
  };
  const tree = [null, shape([])];
  for (let k = 2; k <= n; k++) tree.push(shape(k === 2 ? [tree[1]] : [tree[k - 2], tree[k - 1]]));
  // All shapes reachable by deleting one non-root node together with everything below it.
  const movesMemo = new Map();
  const moves = id => {
    if (movesMemo.has(id)) return movesMemo.get(id);
    const kids = kidsOf[id], result = new Set();
    kids.forEach((kid, i) => {
      const rest = kids.filter((_, j) => j !== i);
      result.add(shape(rest));
      for (const smaller of moves(kid)) result.add(shape([...rest, smaller]));
    });
    movesMemo.set(id, result);
    return result;
  };
  // The player to move wins when some deletion leaves the opponent in a losing shape;
  // with no such deletion left, they must delete the root and lose.
  const winMemo = new Map();
  const wins = id => {
    if (winMemo.has(id)) return winMemo.get(id);
    let result = false;
    for (const next of moves(id)) if (!wins(next)) { result = true; break; }
    winMemo.set(id, result);
    return result;
  };
  return wins(tree[n]);
}

