function generate(rand, size) {
  // The full game search only copes with trees up to order(6).
  if (size === 'small') return [1 + Math.floor(rand() * 6)];
  // Half of the large sizes are one more than a multiple of 6, where the first player loses.
  if (rand() < 0.5) return [61 + 6 * Math.floor(rand() * 7)];
  return [60 + Math.floor(rand() * 41)];
}
